  if(t.paused<t.maxPause){t.vRadX=approach(t.vRadX,t.tRadX,t.mRadX);t.vRadZ=approach(t.vRadZ,t.tRadZ,t.mRadZ);}else{t.vRadX*=.9f;t.vRadZ*=.9f;}t.mRadX*=.9f;t.mRadZ*=.9f;if(t.beamLength>0&&t.paused>t.maxPause)t.beamLength--;
