  var beams=BEAMS.computeIfAbsent(t,k->new BoreBeam[2]);for(int i=0;i<2;i++){if(beams[i]==null||!beams[i].isAlive()){beams[i]=new BoreBeam(l,origin,end,i);Minecraft.getInstance().particleEngine.add(beams[i]);}beams[i].update(end,impact);}t.topRotation+=t.beamLength/6;
